ScPageBreakShell::ScPageBreakShell(ScTabViewShell* pViewSh)
    : SfxShell(pViewSh)
{
    SetPool(&pViewSh->GetPool());
    ScViewData& rViewData = pViewSh->GetViewData();
    SfxUndoManager* pMgr = rViewData.GetSfxDocShell()->GetUndoManager();
